(function(){'use strict';const bank=[{"id":"pharm-e2-user-diuretics16-mcq-001","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #1","q":"What is the principal effect of diuretics on kidney handling of water and solutes?","options":["Increased renal sodium and water reabsorption","Increased production of concentrated urine in every patient","Increased excretion of water, often with sodium and other electrolytes, depending on the diuretic class","Increased extracellular fluid volume"],"answer":2,"why":"Most diuretic classes promote natriuresis and thus increase urine water excretion; aquaretics increase free-water excretion. Resulting urine is not invariably 'large volumes of dilute urine' because concentration depends on nephron site and water handling.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":1,"originalImportedQuestion":"What is the primary physiologic effect of diuretic drugs?","originalImportedAnswer":"Increased production of large volumes of dilute urine","originalImportedWhy":"Uploaded answer key: Increased production of large volumes of dilute urine"},{"id":"pharm-e2-user-diuretics16-mcq-002","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #2","q":"Which fluid compartments are primarily affected by diuretic-induced reductions in extracellular fluid volume?","options":["Vascular and interstitial compartments","Intracellular compartments exclusively","Cerebrospinal fluid exclusively","Intracellular and mitochondrial compartments"],"answer":0,"why":"Uploaded answer key: Vascular and interstitial compartments","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":2},{"id":"pharm-e2-user-diuretics16-mcq-003","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #3","q":"Why does congestive heart failure (CHF) commonly result in fluid retention?","options":["Increased cardiac output suppresses renal filtration.","Reduced aldosterone secretion causes sodium retention.","Increased renal blood flow activates the parasympathetic nervous system.","Reduced cardiac output activates RAAS, promoting sodium and water retention."],"answer":3,"why":"Reduced effective cardiac output in CHF can activate sympathetic and RAAS pathways, increasing aldosterone-mediated renal sodium retention and ADH-mediated water retention. This compensatory response may worsen venous congestion and edema.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":3,"originalImportedQuestion":"Why does congestive heart failure (CHF) commonly result in fluid retention?","originalImportedAnswer":"Reduced cardiac output activates RAAS, promoting sodium and water retention.","originalImportedWhy":"Uploaded answer key: Reduced cardiac output activates RAAS, promoting sodium and water retention."},{"id":"pharm-e2-user-diuretics16-mcq-004","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #4","q":"A dog with CHF develops pulmonary edema and dyspnea. How can diuretic therapy improve its clinical condition?","options":["By increasing pulmonary capillary pressure","By decreasing ECF volume and reducing pulmonary fluid accumulation","By increasing aldosterone secretion","By increasing sodium reabsorption"],"answer":1,"why":"CHF may elevate venous pressure and cause pulmonary fluid accumulation. Renal sodium/water excretion lowers circulating congestion and edema, improving breathing when fluid overload is present.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":4,"originalImportedWhy":"Uploaded answer key: By decreasing ECF volume and reducing pulmonary fluid accumulation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-005","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #5","q":"Which mechanisms contribute to ascites and edema in animals with hepatic cirrhosis?","options":["Increased hepatic blood flow and reduced portal pressure","Suppression of RAAS and increased plasma protein production","Portal hypertension, RAAS activation, and hypoproteinemia","Increased glomerular filtration and reduced sodium retention"],"answer":2,"why":"Portal hypertension favors movement of fluid out of hepatic vessels; reduced oncotic pressure and RAAS activation promote further sodium/water retention. Diuresis treats fluid burden but not the cause of cirrhosis.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":5,"originalImportedWhy":"Uploaded answer key: Portal hypertension, RAAS activation, and hypoproteinemia","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-006","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #6","q":"How can inflammatory renal disease such as nephritis contribute to edema?","options":["Reduced renal blood flow and GFR promote sodium retention and ECF expansion.","Increased GFR causes excessive water excretion.","Increased renal sodium elimination causes vascular expansion.","Reduced ADH activity directly causes edema."],"answer":0,"why":"In some renal disease, reduced effective filtration and increased sodium-retaining signals promote extracellular fluid accumulation. Nephritis does not invariably cause edema; renal physiology and protein loss matter.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":6,"originalImportedWhy":"Uploaded answer key: Reduced renal blood flow and GFR promote sodium retention and ECF expansion.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-007","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #7","q":"What is the underlying mechanism of exercise-induced pulmonary hemorrhage (EIPH) in horses described in the lecture?","options":["Excessive mucus production causing airway obstruction","Increased alveolar surfactant production","Decreased pulmonary capillary pressure during exercise","Rapid increases in capillary transmural pressure causing pulmonary vascular rupture"],"answer":3,"why":"Strenuous exercise raises pulmonary vascular pressures in horses. High capillary transmural pressure can stress or rupture delicate alveolar capillaries and cause hemorrhage.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":7,"originalImportedWhy":"Uploaded answer key: Rapid increases in capillary transmural pressure causing pulmonary vascular rupture","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-008","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #8","q":"Which statement best describes the evidence supporting diuretics in acute oliguric renal failure?","options":["They consistently restore normal renal function.","There is little evidence of benefit, and some evidence suggests potential harm.","They reverse all causes of renal injury.","They are the definitive treatment for acute kidney injury."],"answer":1,"why":"Diuretic-induced urine output does not necessarily improve intrinsic kidney injury or long-term outcome in oliguric AKI. Hypovolemia can worsen perfusion; address the cause and volume status first.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":8,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: There is little evidence of benefit, and some evidence suggests potential harm.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-009","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #9","q":"Approximately what percentage of filtered water is reabsorbed in the proximal tubule according to the lecture?","options":["70%","25%","5%","95%"],"answer":0,"why":"Uploaded answer key: 70%","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":9},{"id":"pharm-e2-user-diuretics16-mcq-010","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #10","q":"Approximately what percentage of water reabsorption is attributed to the descending limb of the loop of Henle in the lecture?","options":["70%","Less than 5%","25%","50%"],"answer":2,"why":"Uploaded answer key: 25%","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":10,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-011","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #11","q":"Which transporter is essential for maintaining the high interstitial osmolarity associated with the loop of Henle?","options":["ENaC","Na⁺/Cl⁻ symporter","Aquaporin-2","NKCC2"],"answer":3,"why":"Uploaded answer key: NKCC2","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":11},{"id":"pharm-e2-user-diuretics16-mcq-012","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #12","q":"Which transporter is particularly important for sodium and chloride movement in the distal convoluted tubule?","options":["NKCC2","Na⁺/Cl⁻ symporter","Aquaporin-2","Mineralocorticoid receptor"],"answer":1,"why":"Uploaded answer key: Na⁺/Cl⁻ symporter","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":12},{"id":"pharm-e2-user-diuretics16-mcq-013","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #13","q":"Which hormone plays an important role in regulating water reabsorption in the collecting duct?","options":["Vasopressin (ADH)","Insulin","Glucagon","Erythropoietin"],"answer":0,"why":"Uploaded answer key: Vasopressin (ADH)","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":13},{"id":"pharm-e2-user-diuretics16-mcq-014","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #14","q":"How do most diuretics increase urinary water excretion?","options":["By increasing the osmotic gradient between tubular fluid and interstitium","By increasing sodium transport into the interstitium","By reducing solute reabsorption, thereby retaining more water in the tubular lumen","By increasing water movement into peritubular capillaries"],"answer":2,"why":"Most diuretics reduce nephron solute reabsorption, leaving osmotically active material in tubular fluid so less water can be reclaimed. Aquaretics increase free-water excretion instead.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":14,"originalImportedWhy":"Uploaded answer key: By reducing solute reabsorption, thereby retaining more water in the tubular lumen","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-015","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #15","q":"Which combination correctly identifies the primary nephron sites of action for major diuretic classes?","options":["Loop diuretics — collecting duct; thiazides — proximal tubule","Osmotic diuretics — distal tubule; spironolactone — loop of Henle","Carbonic anhydrase inhibitors — collecting duct; aquaretics — proximal tubule","Osmotic diuretics — proximal tubule; loop diuretics — thick ascending limb; thiazides — distal tubule"],"answer":3,"why":"Uploaded answer key: Osmotic diuretics — proximal tubule; loop diuretics — thick ascending limb; thiazides — distal tubule","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":15},{"id":"pharm-e2-user-diuretics16-mcq-016","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #16","q":"Which drug is classified as an osmotic diuretic?","options":["Spironolactone","Mannitol","Furosemide","Hydrochlorothiazide"],"answer":1,"why":"Uploaded answer key: Mannitol","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":16},{"id":"pharm-e2-user-diuretics16-mcq-017","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #17","q":"What is the primary mechanism by which mannitol promotes diuresis?","options":["It inhibits NKCC2 transporters.","It antagonizes aldosterone receptors.","It increases osmotic pressure within the tubular lumen, retaining water.","It inhibits sodium channels in the collecting duct."],"answer":2,"why":"Mannitol is filtered into renal tubular fluid but poorly reabsorbed; it holds water osmotically in the lumen. It can also shift water from tissue to plasma initially, so volume and kidney function require assessment.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":17,"originalImportedQuestion":"What is the primary mechanism by which mannitol promotes diuresis?","originalImportedAnswer":"It increases osmotic pressure within the tubular lumen, retaining water.","originalImportedWhy":"Uploaded answer key: It increases osmotic pressure within the tubular lumen, retaining water."},{"id":"pharm-e2-user-diuretics16-mcq-018","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #18","q":"Why is mannitol usually reserved for particular osmotic indications rather than routine long-term diuresis?","options":["It is an IV osmotic agent that can acutely expand vascular volume and requires appropriate kidney function and monitoring.","It irreversibly binds renal transporters.","It strongly activates RAAS as its main mechanism.","It is converted to aldosterone."],"answer":0,"why":"Mannitol is filtered but minimally reabsorbed, increasing tubular osmotic pressure. Its initial vascular-expanding effect, potential for overload and risk if renal excretion is impaired explain why it is not a routine long-term diuretic. Rapid urinary elimination is integral to its desired effect, not proof of weak diuresis.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":18,"originalImportedQuestion":"Why does mannitol have a relatively weak diuretic effect according to the lecture?","originalImportedAnswer":"It is rapidly eliminated in the urine.","originalImportedWhy":"Uploaded answer key: It is rapidly eliminated in the urine."},{"id":"pharm-e2-user-diuretics16-mcq-019","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #19","q":"Which route of administration is emphasized for emergency mannitol therapy?","options":["Oral","Subcutaneous","Intramuscular","Intravenous"],"answer":3,"why":"Uploaded answer key: Intravenous","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":19,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-020","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #20","q":"Which clinical conditions are specifically identified as indications for mannitol?","options":["Chronic CHF and bovine udder edema","Elevated intraocular pressure and intracranial pressure","Hypokalemia and metabolic alkalosis","Chronic anemia and hypoproteinemia"],"answer":1,"why":"Uploaded answer key: Elevated intraocular pressure and intracranial pressure","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":20},{"id":"pharm-e2-user-diuretics16-mcq-021","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #21","q":"A dog presents with an acute increase in intracranial pressure. Which property of mannitol makes it potentially beneficial?","options":["It directly inhibits cerebral sodium channels.","It suppresses cerebrospinal fluid production through aldosterone antagonism.","It creates an osmotic gradient that draws water out of brain tissue.","It stimulates renal erythropoietin production."],"answer":2,"why":"IV mannitol temporarily raises plasma osmolality and can shift water from brain parenchyma into circulation, potentially reducing intracranial pressure; it requires appropriate monitoring.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":21,"originalImportedWhy":"Uploaded answer key: It creates an osmotic gradient that draws water out of brain tissue.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-022","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #22","q":"What is a significant adverse effect associated with rapid intravenous administration of mannitol?","options":["Rapid blood volume expansion and vascular overload","Severe hypovolemia before any vascular expansion","Complete suppression of renal blood flow","Immediate erythrocyte destruction"],"answer":0,"why":"Mannitol draws water from tissues into the bloodstream before excretion. In a patient with compromised heart/kidneys this may cause acute overload or pulmonary edema.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":22,"originalImportedWhy":"Uploaded answer key: Rapid blood volume expansion and vascular overload","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-023","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #23","q":"Why should mannitol be used cautiously in patients susceptible to volume overload?","options":["It causes permanent inhibition of ADH.","It directly increases aldosterone secretion.","It prevents all sodium excretion.","Its initial osmotic effect can expand intravascular volume before fluid is eliminated."],"answer":3,"why":"Initial intravascular volume expansion can worsen congestion before renal excretion catches up. Monitor cardiovascular status, osmolality and kidney function.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":23,"originalImportedWhy":"Uploaded answer key: Its initial osmotic effect can expand intravascular volume before fluid is eliminated.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-024","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #24","q":"Which drug is identified as the model carbonic anhydrase inhibitor (CAI)?","options":["Torsemide","Acetazolamide","Amiloride","Chlorothiazide"],"answer":1,"why":"Uploaded answer key: Acetazolamide","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":24},{"id":"pharm-e2-user-diuretics16-mcq-025","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #25","q":"Where do carbonic anhydrase inhibitors primarily exert their diuretic effects?","options":["Collecting duct","Thick ascending limb","Proximal tubule","Distal convoluted tubule"],"answer":2,"why":"Uploaded answer key: Proximal tubule","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":25},{"id":"pharm-e2-user-diuretics16-mcq-026","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #26","q":"What is the primary renal effect of inhibiting carbonic anhydrase?","options":["Increased retention of sodium and water in tubular fluid","Increased sodium reabsorption into the interstitium","Increased aldosterone receptor activation","Increased potassium retention without sodium loss"],"answer":0,"why":"Carbonic anhydrase inhibition reduces proximal bicarbonate recycling and associated sodium reabsorption. More bicarbonate, sodium and water pass downstream; later nephron segments partially compensate.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":26,"originalImportedWhy":"Uploaded answer key: Increased retention of sodium and water in tubular fluid","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-027","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #27","q":"Which reaction is directly associated with carbonic anhydrase activity?","options":["Conversion of glucose into glycogen","Conversion of angiotensin I into angiotensin II","Conversion of ATP into cAMP","Reversible conversion involving CO₂, H₂O, and H₂CO₃"],"answer":3,"why":"Carbonic anhydrase catalyzes CO₂ hydration and the reversible H₂CO₃/HCO₃⁻/H⁺ equilibrium. Renal inhibition increases bicarbonate loss and can produce metabolic acidosis.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":27,"originalImportedWhy":"Uploaded answer key: Reversible conversion involving CO₂, H₂O, and H₂CO₃","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-028","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #28","q":"Why can acetazolamide be used to treat glaucoma?","options":["It increases aqueous humor drainage through the trabecular meshwork.","It reduces aqueous humor production through carbonic anhydrase inhibition.","It directly dilates the pupil.","It increases intraocular blood flow."],"answer":1,"why":"Carbonic anhydrase is involved in aqueous-humor formation in the ciliary epithelium. Inhibiting it reduces secretion and can lower intraocular pressure.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":28,"originalImportedWhy":"Uploaded answer key: It reduces aqueous humor production through carbonic anhydrase inhibition.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-029","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #29","q":"Which acid-base disorder may be treated using carbonic anhydrase inhibitors according to the lecture?","options":["Respiratory acidosis","Metabolic acidosis","Metabolic alkalosis","Respiratory alkalosis exclusively"],"answer":2,"why":"Uploaded answer key: Metabolic alkalosis","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":29},{"id":"pharm-e2-user-diuretics16-mcq-030","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #30","q":"Which acid-base disturbance is a recognized adverse effect of acetazolamide?","options":["Metabolic acidosis","Metabolic alkalosis","Respiratory alkalosis","Mixed respiratory alkalosis and metabolic alkalosis"],"answer":0,"why":"Uploaded answer key: Metabolic acidosis","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":30},{"id":"pharm-e2-user-diuretics16-mcq-031","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #31","q":"Why does the lecture identify pulmonary disease as a contraindication to carbonic anhydrase inhibitor use?","options":["CAIs directly cause pulmonary vascular rupture.","CAIs irreversibly inhibit surfactant synthesis.","CAIs stimulate bronchoconstriction.","CAIs can cause metabolic acidosis, which may complicate pulmonary disease."],"answer":3,"why":"Carbonic anhydrase inhibitors cause bicarbonate loss and metabolic acidosis, which may complicate existing respiratory acid-base problems. Contraindications depend on a patient's actual ventilation and chemistry.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":31,"originalImportedWhy":"Uploaded answer key: CAIs can cause metabolic acidosis, which may complicate pulmonary disease.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-032","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #32","q":"Why can acetazolamide increase the risk of urolith formation?","options":["It makes urine strongly acidic.","It promotes alkaline urine.","It completely eliminates urinary calcium.","It directly increases urinary protein concentrations."],"answer":1,"why":"Bicarbonate-rich urine becomes more alkaline after carbonic anhydrase inhibition, changing crystal solubility and predisposing susceptible patients to some urolith types.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":32,"originalImportedWhy":"Uploaded answer key: It promotes alkaline urine.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-033","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #33","q":"Which electrolyte abnormality may develop due to the kaliuretic effects of carbonic anhydrase inhibitors?","options":["Hyperkalemia","Hypercalcemia","Hypokalemia","Hypermagnesemia"],"answer":2,"why":"Uploaded answer key: Hypokalemia","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":33},{"id":"pharm-e2-user-diuretics16-mcq-034","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #34","q":"Which combination correctly identifies therapeutic applications and adverse effects of acetazolamide?","options":["Glaucoma and metabolic alkalosis; metabolic acidosis, uroliths, and hypokalemia","CHF and EIPH; ototoxicity and hyperkalemia","CKD-associated anemia; hypertension and erythrocytosis","Bovine udder edema; premature parturition and hypercalcemia"],"answer":0,"why":"Uploaded answer key: Glaucoma and metabolic alkalosis; metabolic acidosis, uroliths, and hypokalemia","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":34,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-035","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #35","q":"Which transporter is directly inhibited by furosemide?","options":["ENaC","Na⁺/Cl⁻ symporter","Aquaporin-2","NKCC2"],"answer":3,"why":"Furosemide blocks NKCC2 in the thick ascending limb, preventing luminal sodium, potassium and chloride reabsorption. This reduces medullary hypertonicity and increases excretion of salt and water.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":35,"originalImportedQuestion":"Which transporter is directly inhibited by furosemide?","originalImportedAnswer":"NKCC2","originalImportedWhy":"Uploaded answer key: NKCC2"},{"id":"pharm-e2-user-diuretics16-mcq-036","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #36","q":"Where does furosemide primarily act within the nephron?","options":["Proximal convoluted tubule","Thick ascending limb of the loop of Henle","Collecting duct","Glomerulus"],"answer":1,"why":"Uploaded answer key: Thick ascending limb of the loop of Henle","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":36},{"id":"pharm-e2-user-diuretics16-mcq-037","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #37","q":"Which ions are normally transported by NKCC2?","options":["Sodium, calcium, and magnesium","Potassium, bicarbonate, and hydrogen","Sodium, potassium, and two chloride ions","Sodium and chloride only"],"answer":2,"why":"Uploaded answer key: Sodium, potassium, and two chloride ions","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":37},{"id":"pharm-e2-user-diuretics16-mcq-038","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #38","q":"How does furosemide promote diuresis?","options":["It prevents solute reabsorption through NKCC2, retaining solutes and water in the tubular lumen.","It increases aldosterone secretion.","It stimulates aquaporin-2 expression.","It increases sodium movement into the interstitium."],"answer":0,"why":"NKCC2 reabsorbs sodium, potassium and chloride in the thick ascending limb. Inhibition leaves solute in urine and weakens the medullary osmotic gradient, increasing water excretion.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":38,"originalImportedWhy":"Uploaded answer key: It prevents solute reabsorption through NKCC2, retaining solutes and water in the tubular lumen.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-039","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #39","q":"How is furosemide characterized pharmacologically?","options":["A weak potassium-sparing diuretic","A weak drug that always produces irreversible toxicity","A low-ceiling carbonic anhydrase inhibitor","A potent, high-ceiling loop diuretic that requires monitoring for dehydration, electrolyte disturbances and renal effects"],"answer":3,"why":"Furosemide inhibits NKCC2 in the thick ascending limb, a major NaCl-reabsorbing segment. High-ceiling natriuresis is useful for congestion but can cause hypovolemia, hypokalemia, hypochloremia and prerenal azotemia; calling its therapeutic index universally high can obscure these risks.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":39,"originalImportedQuestion":"Which statement best describes furosemide's potency and therapeutic index according to the lecture?","originalImportedAnswer":"Potent, high-ceiling diuretic with a high therapeutic index","originalImportedWhy":"Uploaded answer key: Potent, high-ceiling diuretic with a high therapeutic index"},{"id":"pharm-e2-user-diuretics16-mcq-040","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #40","q":"Approximately when does furosemide reach peak effects following intravenous administration?","options":["5 hours","30 minutes","12 hours","24 hours"],"answer":1,"why":"Uploaded answer key: 30 minutes","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":40},{"id":"pharm-e2-user-diuretics16-mcq-041","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #41","q":"Approximately when does oral furosemide reach peak effects according to the lecture?","options":["15 minutes","8 hours","2 hours","24 hours"],"answer":2,"why":"Uploaded answer key: 2 hours","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":41},{"id":"pharm-e2-user-diuretics16-mcq-042","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #42","q":"What duration of action is listed for furosemide?","options":["4-5 hours","12-18 hours","24 hours","48 hours"],"answer":0,"why":"Uploaded answer key: 4-5 hours","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":42,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-043","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #43","q":"Which adverse effect is specifically associated with furosemide's action on the cochlea?","options":["Retinal degeneration","Vestibular paralysis exclusively","Permanent blindness","Ototoxicity, potentially resulting in reversible hearing loss"],"answer":3,"why":"Loop diuretics can impair electrolyte handling in the inner ear, especially with high exposure or interacting ototoxic drugs, resulting in hearing disturbance.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":43,"originalImportedWhy":"Uploaded answer key: Ototoxicity, potentially resulting in reversible hearing loss","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-044","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #44","q":"What is the braking effect associated with furosemide administration?","options":["Permanent inhibition of glomerular filtration","RAAS activation in response to reduced blood volume, promoting sodium and water retention","Direct inhibition of aldosterone synthesis","Increased aquaporin degradation"],"answer":1,"why":"Falling effective circulating volume activates RAAS and sodium-conserving mechanisms, partially counteracting continued furosemide natriuresis ('diuretic braking').","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":44,"originalImportedWhy":"Uploaded answer key: RAAS activation in response to reduced blood volume, promoting sodium and water retention","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-045","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #45","q":"Why may furosemide become less effective with repeated administration?","options":["It permanently destroys NKCC2 transporters.","It stimulates renal erythropoietin production.","Compensatory RAAS activation promotes sodium and water retention.","It directly increases plasma oncotic pressure."],"answer":2,"why":"The kidney adapts to repeated sodium loss by activating RAAS and enhancing distal sodium reabsorption, so effective natriuresis may decline despite similar dosing.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":45,"originalImportedWhy":"Uploaded answer key: Compensatory RAAS activation promotes sodium and water retention.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-046","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #46","q":"Which clinical application of furosemide is especially important in horses?","options":["Prevention of exercise-induced pulmonary hemorrhage","Treatment of CKD-associated anemia","Prevention of equine laminitis","Treatment of equine hypocalcemia"],"answer":0,"why":"Uploaded answer key: Prevention of exercise-induced pulmonary hemorrhage","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":46,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-047","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #47","q":"Why must equine furosemide withdrawal rules be verified for the particular jurisdiction and competition?","options":["Furosemide is approved for all slaughter horses without restriction.","A single worldwide 14-day competition withdrawal rule applies.","Equine withdrawal times never change.","Rules vary with jurisdiction, racing/competition organization, indication and horse status; a lecture's 48-hour figure is not universal."],"answer":3,"why":"Competition regulations, testing windows and food-animal restrictions are distinct legal contexts; a course figure should not be substituted for the applicable official rules.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":47,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedQuestion":"Which statement regarding furosemide use in horses is identified in the lecture?","originalImportedAnswer":"The lecture lists a 48-hour withdrawal time and cautions against use in horses destined for consumption.","originalImportedWhy":"Uploaded answer key: The lecture lists a 48-hour withdrawal time and cautions against use in horses destined for consumption."},{"id":"pharm-e2-user-diuretics16-mcq-048","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #48","q":"Why is furosemide useful as an adjunctive medication for CHF?","options":["It directly increases myocardial contractility.","It reduces ECF volume, decreasing fluid accumulation in the lungs.","It increases circulating blood volume.","It directly inhibits cardiac beta-1 receptors."],"answer":1,"why":"Removing excess sodium and water reduces vascular congestion and pulmonary edema. Excessive volume removal can reduce cardiac preload and kidney perfusion, so dose response must be monitored.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":48,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: It reduces ECF volume, decreasing fluid accumulation in the lungs.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-049","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #49","q":"Which medication is mentioned as being compounded with furosemide for adjunctive hypertension treatment?","options":["Digoxin","Pimobendan","Enalapril","Dexamethasone"],"answer":2,"why":"Uploaded answer key: Enalapril","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":49},{"id":"pharm-e2-user-diuretics16-mcq-050","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #50","q":"Why is furosemide preferred over dexamethasone for pre-parturient bovine udder edema according to the lecture?","options":["Furosemide does not prematurely induce parturition.","Furosemide has no milk withholding requirement.","Dexamethasone is ineffective against edema.","Furosemide directly increases milk production."],"answer":0,"why":"Furosemide mobilizes edema through NKCC2 blockade without the glucocorticoid-driven endocrine effects that may accelerate parturition in pregnant cattle. Food-animal rules must be confirmed.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":50,"originalImportedWhy":"Uploaded answer key: Furosemide does not prematurely induce parturition.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-051","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #51","q":"Which source must determine the milk withholding interval after furosemide use in a dairy cow?","options":["The number of hours since milking alone","A fixed 24-hour interval for any formulation","The shortest interval stated by a classmate","The applicable product label and veterinary regulatory guidance for the exact drug, route and food-animal status"],"answer":3,"why":"Milk withdrawal periods vary by approved product, dose, route, jurisdiction and legal extra-label use. An isolated 48-hour lecture figure is not universally safe for residue avoidance.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":51,"originalImportedQuestion":"What milk withholding period is listed for furosemide in cattle in the lecture?","originalImportedAnswer":"48 hours","originalImportedWhy":"Uploaded answer key: 48 hours"},{"id":"pharm-e2-user-diuretics16-mcq-052","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #52","q":"Which alternative treatment for bovine udder edema may induce parturition?","options":["Spironolactone","Dexamethasone","Amiloride","Mannitol"],"answer":1,"why":"Uploaded answer key: Dexamethasone","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":52,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-053","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #53","q":"Which species is specifically identified as having an approved torsemide product in the lecture?","options":["Horses","Cattle","Dogs","Swine"],"answer":2,"why":"Uploaded answer key: Dogs","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":53,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-054","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #54","q":"How does torsemide compare with furosemide on a per-milligram basis?","options":["Torsemide produces greater diuresis.","Torsemide is substantially less potent.","Torsemide has no diuretic effect.","Torsemide exclusively causes aquaresis."],"answer":0,"why":"Torsemide is more potent per mg at NKCC2 inhibition and often longer acting than furosemide. Dose conversion requires a separate plan, not copying the previous number of milligrams.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":54,"originalImportedWhy":"Uploaded answer key: Torsemide produces greater diuresis.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-055","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #55","q":"Which pharmacokinetic characteristic contributes to smoother diuresis with torsemide?","options":["Immediate and complete elimination","Rapid irreversible receptor binding","Complete lack of oral absorption","Slower onset of action"],"answer":3,"why":"Torsemide's onset and duration can produce a more sustained diuretic effect than short-acting furosemide. Individual responses vary with renal perfusion and congestion.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":55,"originalImportedWhy":"Uploaded answer key: Slower onset of action","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-056","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #56","q":"What is a major disadvantage of torsemide's increased potency?","options":["It cannot be administered orally.","Small dose differences may result in under-diuresis or over-diuresis.","It cannot produce clinically meaningful diuresis.","It irreversibly damages the glomerulus."],"answer":1,"why":"Greater potency and sustained activity amplify the consequences of a small dosing error. Kidney function, electrolytes, hydration and blood pressure need assessment.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":56,"originalImportedWhy":"Uploaded answer key: Small dose differences may result in under-diuresis or over-diuresis.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-057","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #57","q":"Which combination of medications is specifically identified as approved alongside torsemide for pulmonary edema secondary to CHF?","options":["Dexamethasone, mannitol, and acetazolamide","Digoxin, atropine, and hydrochlorothiazide","Pimobendan, spironolactone, and an ACE inhibitor","Amiloride, triamterene, and erythropoietin"],"answer":2,"why":"Uploaded answer key: Pimobendan, spironolactone, and an ACE inhibitor","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":57},{"id":"pharm-e2-user-diuretics16-mcq-058","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #58","q":"Which characteristic makes torsemide potentially advantageous for patients requiring sustained diuresis?","options":["Longer duration of action","Shorter duration than furosemide","Complete elimination of electrolyte disturbances","Absence of any RAAS effects"],"answer":0,"why":"Uploaded answer key: Longer duration of action","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":58,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-059","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #59","q":"A dog with CHF requires a longer-acting diuretic, but the veterinarian is concerned about excessive fluid loss from small dose adjustments. Which drug best fits this description?","options":["Mannitol","Acetazolamide","Amiloride","Torsemide"],"answer":3,"why":"Uploaded answer key: Torsemide","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":59},{"id":"pharm-e2-user-diuretics16-mcq-060","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #60","q":"Which transporter is inhibited by thiazide diuretics?","options":["NKCC2","Na⁺/Cl⁻ symporter","ENaC","Aquaporin-2"],"answer":1,"why":"Uploaded answer key: Na⁺/Cl⁻ symporter","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":60},{"id":"pharm-e2-user-diuretics16-mcq-061","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #61","q":"Where do thiazide diuretics primarily act?","options":["Proximal tubule","Thick ascending limb","Distal convoluted tubule","Collecting duct"],"answer":2,"why":"Uploaded answer key: Distal convoluted tubule","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":61},{"id":"pharm-e2-user-diuretics16-mcq-062","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #62","q":"Which medications are classified as thiazide diuretics in the lecture?","options":["Chlorothiazide and hydrochlorothiazide","Furosemide and torsemide","Spironolactone and amiloride","Mannitol and acetazolamide"],"answer":0,"why":"Uploaded answer key: Chlorothiazide and hydrochlorothiazide","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":62},{"id":"pharm-e2-user-diuretics16-mcq-063","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #63","q":"What happens when the Na⁺/Cl⁻ symporter is inhibited by a thiazide diuretic?","options":["Sodium is increasingly reabsorbed into the blood.","Water is directly transported into the interstitium.","Potassium secretion is completely prevented.","Sodium remains in the tubular lumen, promoting water retention in the filtrate."],"answer":3,"why":"Thiazide inhibition of distal NCC prevents sodium/chloride recovery, increasing solute delivery beyond that nephron segment and promoting urinary water loss.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":63,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: Sodium remains in the tubular lumen, promoting water retention in the filtrate.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-064","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #64","q":"According to the lecture, where do thiazides rank for CHF treatment relative to loop diuretics?","options":["First-line and more potent than loop diuretics","Second choice behind loop diuretics","Contraindicated in all CHF patients","Only used when aquaretics fail"],"answer":1,"why":"Uploaded answer key: Second choice behind loop diuretics","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":64},{"id":"pharm-e2-user-diuretics16-mcq-065","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #65","q":"Which thiazide is identified as approved in cattle for udder edema?","options":["Chlorothiazide","Metolazone","Hydrochlorothiazide","Torsemide"],"answer":2,"why":"Uploaded answer key: Hydrochlorothiazide","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":65,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-066","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #66","q":"What should guide a milk or meat withdrawal interval when hydrochlorothiazide is considered in cattle?","options":["A verified approved label and applicable food-animal prescribing/residue guidance","An arbitrary 24-hour interval","A universal 48-hour interval for all diuretics","A seven-day interval irrespective of route"],"answer":0,"why":"Withholding periods depend on product and jurisdiction. The old 72-hour memorization question lacked context and should not be treated as general prescribing guidance.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":66,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedQuestion":"What withholding period is listed for hydrochlorothiazide in cattle?","originalImportedAnswer":"72 hours","originalImportedWhy":"Uploaded answer key: 72 hours"},{"id":"pharm-e2-user-diuretics16-mcq-067","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #67","q":"Which effect on calcium handling is associated with thiazide diuretics?","options":["Complete inhibition of calcium reabsorption","Increased urinary calcium excretion in all patients","No effect on renal calcium handling","Increased renal calcium reabsorption"],"answer":3,"why":"Thiazides block NCC in distal convoluted tubule cells and enhance calcium reabsorption, decreasing urinary calcium loss; this differs from loop diuretics, which often increase calcium excretion.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":67,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedQuestion":"Which effect on calcium handling is associated with thiazide diuretics?","originalImportedAnswer":"Increased renal calcium reabsorption","originalImportedWhy":"Uploaded answer key: Increased renal calcium reabsorption"},{"id":"pharm-e2-user-diuretics16-mcq-068","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #68","q":"Which statement correctly describes drug interactions involving thiazide diuretics?","options":["NSAIDs enhance their effects, and they increase insulin efficacy.","NSAIDs may impair their effects, and thiazides may impair the effects of anticoagulants and insulin.","They have no clinically relevant drug interactions.","They permanently inhibit all anticoagulant medications."],"answer":1,"why":"NSAID blockade of renal prostaglandin production can blunt natriuretic response to diuretics. Thiazides can change glucose control and electrolytes; other interaction claims depend on specific drugs and indications.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":68,"originalImportedWhy":"Uploaded answer key: NSAIDs may impair their effects, and thiazides may impair the effects of anticoagulants and insulin.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-069","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #69","q":"Which receptor is directly antagonized by spironolactone?","options":["Vasopressin V2 receptor","Beta-1 adrenergic receptor","Mineralocorticoid receptor","Angiotensin II AT1 receptor"],"answer":2,"why":"Spironolactone competitively antagonizes mineralocorticoid receptors in distal nephron principal cells, reducing aldosterone-stimulated ENaC activity and potassium secretion. It is potassium-sparing and can cause hyperkalemia.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":69,"originalImportedQuestion":"Which receptor is directly antagonized by spironolactone?","originalImportedAnswer":"Mineralocorticoid receptor","originalImportedWhy":"Uploaded answer key: Mineralocorticoid receptor"},{"id":"pharm-e2-user-diuretics16-mcq-070","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #70","q":"Where does spironolactone primarily exert its renal effects?","options":["Principal cells of the late distal tubule and collecting duct","Proximal tubular epithelial cells","Thick ascending limb cells","Glomerular endothelial cells"],"answer":0,"why":"Uploaded answer key: Principal cells of the late distal tubule and collecting duct","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":70},{"id":"pharm-e2-user-diuretics16-mcq-071","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #71","q":"What is the primary effect of aldosterone on renal sodium handling?","options":["It inhibits sodium reabsorption.","It promotes sodium loss into the urine.","It directly inhibits ENaC activity.","It promotes sodium reabsorption through mineralocorticoid receptor signaling."],"answer":3,"why":"Uploaded answer key: It promotes sodium reabsorption through mineralocorticoid receptor signaling.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":71,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-072","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #72","q":"How does spironolactone promote diuresis?","options":["By directly inhibiting NKCC2","By blocking aldosterone-mediated sodium reabsorption, retaining sodium and water in the tubular lumen","By directly increasing glomerular filtration","By increasing aquaporin-2 expression"],"answer":1,"why":"Spironolactone antagonizes mineralocorticoid receptor signaling, reducing ENaC-mediated sodium uptake in distal nephron principal cells. Sodium remains in tubular fluid, with relatively weak diuresis.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":72,"originalImportedWhy":"Uploaded answer key: By blocking aldosterone-mediated sodium reabsorption, retaining sodium and water in the tubular lumen","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-073","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #73","q":"Why is spironolactone considered potassium-sparing?","options":["It increases potassium filtration.","It increases potassium secretion into the collecting duct.","It limits aldosterone-mediated potassium secretion.","It directly increases potassium excretion."],"answer":2,"why":"Aldosterone normally stimulates sodium absorption and promotes potassium secretion. Blocking its receptor reduces renal potassium loss but creates hyperkalemia risk.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":73,"originalImportedWhy":"Uploaded answer key: It limits aldosterone-mediated potassium secretion.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-074","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #74","q":"Which electrolyte abnormality is a significant precaution with spironolactone therapy?","options":["Hyperkalemia","Hypokalemia","Hypernatremia","Hypochloremia exclusively"],"answer":0,"why":"Uploaded answer key: Hyperkalemia","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":74},{"id":"pharm-e2-user-diuretics16-mcq-075","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #75","q":"Why is spironolactone commonly combined with other diuretics rather than used alone?","options":["It is a stronger diuretic than furosemide.","It causes complete renal shutdown when administered alone.","It has no effects on potassium handling.","It has weak diuretic effects but can enhance diuresis and limit potassium loss."],"answer":3,"why":"Spironolactone acts late in the nephron and has weak immediate natriuretic activity. Combined therapy may complement loop effects while requiring renal and potassium monitoring.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":75,"originalImportedWhy":"Uploaded answer key: It has weak diuretic effects but can enhance diuresis and limit potassium loss.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-076","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #76","q":"What interaction is identified between spironolactone and digoxin?","options":["Spironolactone immediately eliminates digoxin.","Spironolactone increases digoxin's half-life, potentially requiring a lower digoxin dose.","Spironolactone prevents digoxin absorption.","Spironolactone permanently inactivates digoxin."],"answer":1,"why":"Spironolactone and its metabolites can alter digoxin handling or some assay measurements. Interpret levels and clinical toxicity with medication history; avoid assuming a fixed dose reduction.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":76,"originalImportedWhy":"Uploaded answer key: Spironolactone increases digoxin's half-life, potentially requiring a lower digoxin dose.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-077","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #77","q":"Which reproductive adverse effect may occur in male animals receiving spironolactone?","options":["Increased testosterone receptor activation","Increased sperm production exclusively","Antiandrogenic effects due to androgen receptor antagonism","Increased androgen synthesis"],"answer":2,"why":"Uploaded answer key: Antiandrogenic effects due to androgen receptor antagonism","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":77,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-078","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #78","q":"What is aldosterone breakthrough during ACE inhibitor therapy?","options":["Continued aldosterone activity despite ACE inhibition because RAAS blockade is incomplete","Complete elimination of aldosterone secretion","Permanent inhibition of renin production","Increased potassium excretion caused by aquaretics"],"answer":0,"why":"Aldosterone secretion may persist despite ACE inhibition because other pathways can generate angiotensin II or regulate aldosterone. Mineralocorticoid antagonists can complement RAAS blockade.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":78,"originalImportedWhy":"Uploaded answer key: Continued aldosterone activity despite ACE inhibition because RAAS blockade is incomplete","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-079","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #79","q":"Why is combining spironolactone with an ACE inhibitor beneficial in CHF?","options":["It increases angiotensin II production.","It directly increases vascular resistance.","It stimulates aldosterone-mediated sodium retention.","It provides more complete RAAS blockade, improving ECF control and limiting aldosterone-associated inflammation and fibrosis."],"answer":3,"why":"Mineralocorticoid receptor blockade can reduce aldosterone-driven retention and myocardial remodeling. ACE inhibition alone may not abolish aldosterone; monitor potassium and renal function on combinations.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":79,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: It provides more complete RAAS blockade, improving ECF control and limiting aldosterone-associated inflammation and fibrosis.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-080","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #80","q":"Which drugs directly inhibit epithelial sodium channels (ENaC)?","options":["Furosemide and torsemide","Triamterene and amiloride","Chlorothiazide and hydrochlorothiazide","Mannitol and acetazolamide"],"answer":1,"why":"Uploaded answer key: Triamterene and amiloride","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":80,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-081","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #81","q":"Why do many diuretics promote hypokalemia?","options":["They directly destroy potassium in the renal tubules.","They increase intracellular potassium synthesis.","Increased distal sodium delivery promotes sodium reabsorption and potassium secretion through distal nephron transport processes.","They prevent potassium filtration at the glomerulus."],"answer":2,"why":"Increased sodium delivery to the collecting duct enhances ENaC-mediated sodium absorption, creating an electrochemical gradient favoring potassium secretion. Loop and thiazide therapy can therefore lower potassium.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":81,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: Increased distal sodium delivery promotes sodium reabsorption and potassium secretion through distal nephron transport processes.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-082","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #82","q":"What is a major adverse effect of triamterene and amiloride?","options":["Hyperkalemia","Hypokalemia","Ototoxicity","Metabolic alkalosis exclusively"],"answer":0,"why":"Uploaded answer key: Hyperkalemia","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":82,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use."},{"id":"pharm-e2-user-diuretics16-mcq-083","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #83","q":"Why are triamterene and amiloride relatively uncommon in veterinary medicine according to the lecture?","options":["They are more potent than furosemide.","They irreversibly damage the collecting duct.","They cannot be combined with other diuretics.","They provide weak diuresis, and spironolactone is generally considered a better potassium-sparing option."],"answer":3,"why":"ENaC blockers have limited natriuretic strength compared with loop diuretics and are mainly considered as adjuncts. Preferences vary by patient and clinical availability.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":83,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: They provide weak diuresis, and spironolactone is generally considered a better potassium-sparing option.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-084","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #84","q":"Which mechanism is responsible for the action of aquaretic medications such as mozavaptan?","options":["Inhibition of NKCC2","Vasopressin receptor antagonism, reducing aquaporin-2-mediated water reabsorption","Mineralocorticoid receptor activation","Direct inhibition of carbonic anhydrase"],"answer":1,"why":"Vasopressin receptor antagonists reduce collecting-duct V2 signaling, lowering aquaporin-2 insertion and free-water reabsorption. The resulting aquaresis differs from natriuresis because relatively little sodium is directly excreted.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":84,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedQuestion":"Which mechanism is responsible for the action of aquaretic medications such as mozavaptan?","originalImportedAnswer":"Vasopressin receptor antagonism, reducing aquaporin-2-mediated water reabsorption","originalImportedWhy":"Uploaded answer key: Vasopressin receptor antagonism, reducing aquaporin-2-mediated water reabsorption"},{"id":"pharm-e2-user-diuretics16-mcq-085","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #85","q":"What distinguishes aquaresis from traditional diuresis?","options":["Aquaresis exclusively increases sodium excretion.","Aquaresis increases potassium secretion.","Aquaresis promotes water excretion without accompanying electrolyte excretion.","Aquaresis requires direct NKCC2 inhibition."],"answer":2,"why":"Aquaretics antagonize vasopressin-dependent aquaporin-2 insertion, allowing relatively electrolyte-poor water to be excreted. This differs from natriuretic agents that increase urinary sodium delivery.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":85,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: Aquaresis promotes water excretion without accompanying electrolyte excretion.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-086","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #86","q":"Why can excessive diuretic administration cause pre-renal azotemia?","options":["Hypovolemia reduces renal blood flow, increasing BUN and other markers of azotemia.","Diuretics directly increase erythropoietin production.","Increased blood volume causes glomerular hypertension.","Increased renal perfusion reduces urine production."],"answer":0,"why":"Excessive sodium/water removal lowers renal perfusion pressure and GFR, increasing BUN and potentially creatinine. Prerenal azotemia may improve when perfusion is restored, unlike fixed structural renal damage.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":86,"originalImportedWhy":"Uploaded answer key: Hypovolemia reduces renal blood flow, increasing BUN and other markers of azotemia.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-087","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #87","q":"Which acid-base disturbance can develop due to preferential chloride loss during diuretic therapy?","options":["Respiratory acidosis","Metabolic acidosis exclusively","Respiratory alkalosis","Metabolic alkalosis"],"answer":3,"why":"Loop- and thiazide-associated chloride depletion and increased distal H⁺ secretion can maintain metabolic alkalosis; the pattern depends on drug class and volume status.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":87,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: Metabolic alkalosis","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-088","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #88","q":"Which monitoring and management approach is recommended for animals receiving diuretics?","options":["Avoid bloodwork unless clinical collapse occurs.","Monitor capillary refill time and bloodwork, correct fluid/electrolyte disturbances, and use the lowest effective dose.","Increase the dose whenever urine production decreases without reassessment.","Eliminate all dietary potassium without checking electrolytes."],"answer":1,"why":"Recheck body weight, hydration, renal values and electrolytes after diuretic adjustments. A low dose is not necessarily safe if renal perfusion or intake changes.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":88,"originalImportedWhy":"Uploaded answer key: Monitor capillary refill time and bloodwork, correct fluid/electrolyte disturbances, and use the lowest effective dose.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-089","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #89","q":"Which statement correctly describes hypoxia-inducible factor (HIF) and erythropoietin (EPO) regulation?","options":["HIF permanently suppresses erythropoietin production.","HIF prolyl-hydroxylase directly stimulates red blood cell destruction.","HIF promotes EPO gene transcription, while HIF prolyl-hydroxylase normally promotes HIF degradation.","EPO inhibits erythrocyte production."],"answer":2,"why":"Prolyl hydroxylases normally mark HIF for degradation when oxygen is sufficient. Inhibition stabilizes HIF and can increase endogenous EPO transcription and erythropoiesis.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":89,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: HIF promotes EPO gene transcription, while HIF prolyl-hydroxylase normally promotes HIF degradation.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diuretics16-mcq-090","lecture":"Lecture 16","sourceGroup":"Lecture 16 · uploaded MCQ set","topic":"Diuretics & Renal Pharmacology · #90","q":"A cat with chronic kidney disease develops persistent nonregenerative anemia. Which combination correctly identifies the two treatment options discussed in the lecture?","options":["Oral molidustat, a HIF prolyl-hydroxylase inhibitor, and injectable darbepoetin, an EPO analog","Oral furosemide and injectable mannitol","Oral spironolactone and injectable torsemide","Oral hydrochlorothiazide and injectable acetazolamide"],"answer":0,"why":"Darbepoetin supplies an exogenous erythropoiesis-stimulating signal, while molidustat stabilizes HIF to increase endogenous EPO-related pathways. Check feline label/eligibility and monitor anemia, iron status and possible adverse effects.","source":"User-supplied Lecture 16 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":90,"reviewFlag":"Lecture-specific clinical, timing, regulatory, withholding, or drug approval statement; preserve original answer and independently verify for real clinical use.","originalImportedWhy":"Uploaded answer key: Oral molidustat, a HIF prolyl-hydroxylase inhibitor, and injectable darbepoetin, an EPO analog","rationaleStatus":"reviewed-mechanism"}];const target=window.VPQ_PHARM_EXAM2_PDF_PRACTICE||(window.VPQ_PHARM_EXAM2_PDF_PRACTICE=[]);const ids=new Set(target.map(x=>x.id));for(const q of bank){if(!ids.has(q.id)){target.push(q);ids.add(q.id)}}window.VPQ_PHARM_DIURETICS16_UPLOADED_MCQ_COUNT=bank.length;})();
